// MONTMORY V80: Original-GPX der Beispieltour offline eingebettet.
document.addEventListener('DOMContentLoaded', () => {
  const button = document.getElementById('loadExampleGpx');
  const input = document.getElementById('gpxFile');
  const status = document.getElementById('status');
  if (!button || !input) return;
  button.addEventListener('click', () => {
    try {
      const binary = atob('');
      const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
      const file = new File([bytes], 'Schwangau-Wandern-Beispieltour.gpx', {type:'application/gpx+xml'});
      const transfer = new DataTransfer();
      transfer.items.add(file);
      input.files = transfer.files;
      input.dispatchEvent(new Event('change', {bubbles:true}));
    } catch (error) {
      if (status) status.textContent = 'Beispieltour konnte nicht geladen werden: ' + error.message;
    }
  });
});
